public class AttendanceSheetManagement { static class AttendanceSheet { private final String[] names; private int count; AttendanceSheet(int size){names=new String[size];} boolean isPresent(String name){for(int i=0;i<count;i++)if(names[i].equals(name))return true;return false;} void markPresent(String name){if(count<names.length&&!isPresent(name))names[count++]=name;} int getPresentCount(){return count;} } public static void main(String[]args){AttendanceSheet sheet=new AttendanceSheet(30);sheet.markPresent("Ana");sheet.markPresent("Ben");sheet.markPresent("Ana");System.out.println("Present: "+sheet.getPresentCount());System.out.println("Ben present: "+sheet.isPresent("Ben"));} }
